/**
 * `fixtures/ics/`, the conformance set of the `.ics` module (docs/EVENTS.md
 * §5.6, task C8), shared by TypeScript and C#: generated by `pnpm fixtures`
 * through the zone fixture hook of `events-file.ts`, so every expectation that
 * needs zone data is computed through the recording resolver and replays
 * through the `RecordedZoneResolver` of `fixtures/events.json` (§5.5).
 *
 * Everything under `fixtures/ics` is generated, inputs included (they are
 * kept in `ics-cases.ts` as content lines, so their exact bytes cannot drift),
 * and the generator removes files it no longer writes.
 * @module
 */

import type { ZoneResolver } from '../src/events/index.ts';
import { parseICalendar, serializeICalendar } from '../src/ics/index.ts';
import type { GeneratedFile } from './events-file.ts';
import { DEFAULT_WINDOW, DEVICE_ZONES, ICS_CASES, ICS_NOW, type IcsCase, type RoundTrip, type WindowSpec, caseCalendarId, caseExpansions } from './ics-cases.ts';
import { icsCalendarJson, icsGroupJson, icsWarningJson, renderFixtureJson } from './ics-json.ts';
import { type ProcedureSpec, buildProcedure, expansionJson } from './ics-procedures.ts';
import { EDIT_SPECS, IMPORT_SPECS, RESTORE_SPEC, RESTORE_ZIP, importInputs, restoreCalendars, restoreInputs, restoreZip } from './ics-scenarios.ts';

/** `fixtures/ics/`. */
export const ICS_DIR_URL: URL = new URL('../../../fixtures/ics/', import.meta.url);

/** Pretty-printed arrays of the expected and procedure files. */
const PRETTY = new Set(['expansions', 'scenarios', 'steps']);

/** A text with CRLF line ends and without a byte order mark: what the writer gives back for a text it copies as read. */
export const normalizeLineEnds = (text: string): string => text.replace(/^﻿/, '').replace(/\r\n|\r|\n/g, '\r\n');

/** A text without the `VTIMEZONE`s Thirteen generated (`X-THIRTEEN-GENERATED`). */
export function withoutGeneratedZones(text: string): string {
  return text.replace(/BEGIN:VTIMEZONE\r\n(?:(?!END:VTIMEZONE\r\n)[\s\S])*?X-THIRTEEN-GENERATED:[\s\S]*?END:VTIMEZONE\r\n/g, '');
}

/** `true` when a round trip relates to its input as the case says. */
export function roundTripHolds(kind: RoundTrip, input: string, output: string): boolean {
  const normalized = normalizeLineEnds(input);
  return kind === 'as-read' ? output === normalized : output !== normalized && withoutGeneratedZones(output) === normalized;
}

/** The expected JSON of a case (see the README for its form). */
export function expectedCaseJson(c: IcsCase, text: string, zones: ZoneResolver): object {
  const calendarId = caseCalendarId(c.file);
  const calendar = parseICalendar(text, { calendarId, zones });
  return {
    version: 1,
    case: `cases/${c.file}`,
    calendarId,
    system: 'ifc',
    roundTrip: c.roundTrip,
    calendar: icsCalendarJson(calendar),
    warnings: calendar.warnings.map(icsWarningJson),
    groups: calendar.groups.map(icsGroupJson),
    expansions: caseExpansions(c).map((e) => expansionJson(text, calendarId, e.deviceZone, e.window, zones)),
  };
}

/** `serializeICalendar(parseICalendar(input))` of a case, at {@link ICS_NOW}. */
export function roundTripText(c: IcsCase, text: string, zones: ZoneResolver): string {
  return serializeICalendar(parseICalendar(text, { calendarId: caseCalendarId(c.file), zones }), zones, { now: ICS_NOW });
}

const caseStem = (file: string) => file.replace(/\.ics$/, '');

/**
 * Every file of `fixtures/ics`, by path relative to it: the inputs, the
 * expected JSON and round trips of every case, the procedure files and the
 * documents of their steps, the restore zip, `index.json`, the README and the
 * attribute files that keep the bytes exact.
 * @throws Error when a case's round trip does not relate to its input as the case says.
 */
export function buildIcsFiles(zones: ZoneResolver): Map<string, string | Uint8Array> {
  const texts = new Map<string, string>();
  for (const c of ICS_CASES) texts.set(`cases/${c.file}`, c.text(zones));
  for (const [path, text] of importInputs(zones)) texts.set(path, text);
  for (const [path, text] of restoreInputs(zones)) texts.set(path, text);
  /** The inputs of the procedures (the cases are listed with their expected files). */
  const inputs = [...texts.keys()].filter((p) => !p.startsWith('cases/'));

  const out = new Map<string, string | Uint8Array>();
  for (const c of ICS_CASES) {
    const text = texts.get(`cases/${c.file}`)!;
    const roundTrip = roundTripText(c, text, zones);
    if (!roundTripHolds(c.roundTrip, text, roundTrip)) throw new Error(`The round trip of ${c.file} is not '${c.roundTrip}'`);
    out.set(`expected/${caseStem(c.file)}.json`, renderFixtureJson(expectedCaseJson(c, text, zones), PRETTY));
    out.set(`roundtrip/${c.file}`, roundTrip);
  }

  const procedure = (spec: ProcedureSpec, extra: object = {}) => {
    const file = buildProcedure(spec, texts, zones, ICS_NOW);
    const { scenarios, ...head } = file;
    out.set(spec.file, renderFixtureJson({ ...head, ...extra, scenarios }, PRETTY));
  };
  for (const spec of EDIT_SPECS) procedure(spec);
  for (const spec of IMPORT_SPECS) procedure(spec);
  procedure(RESTORE_SPEC, {
    calendars: restoreCalendars(texts),
    zip: { file: RESTORE_ZIP, entries: ['Personal.ics', 'Work.ics', 'Holidays in Estonia.ics'] },
  });
  out.set(RESTORE_ZIP, restoreZip(texts));
  for (const [path, text] of texts) out.set(path, text);

  out.set(
    'index.json',
    renderFixtureJson({
      version: 1,
      complete: true,
      generatedBy: '@thirteen/core',
      spec: 'docs/EVENTS.md',
      zoneOffsets: 'fixtures/events.json',
      now: ICS_NOW,
      system: 'ifc',
      deviceZones: [...DEVICE_ZONES],
      defaultWindow: DEFAULT_WINDOW,
      counts: { cases: ICS_CASES.length, edits: EDIT_SPECS.length, imports: IMPORT_SPECS.length, restore: 1, inputs: inputs.length },
      cases: ICS_CASES.map((c) => ({ file: `cases/${c.file}`, expected: `expected/${caseStem(c.file)}.json`, roundtrip: `roundtrip/${c.file}`, roundTrip: c.roundTrip })),
      edits: EDIT_SPECS.map((s) => s.file),
      imports: IMPORT_SPECS.map((s) => s.file),
      restore: [RESTORE_SPEC.file],
      inputs,
    }),
  );
  out.set('README.md', readme());
  out.set('.gitattributes', '# Every byte of these fixtures is exact (CRLF, LF and CR line ends, a byte order mark): no conversion on checkout.\n* -text\n');
  out.set(
    '.editorconfig',
    '# Every byte of these fixtures is exact (line ends, a byte order mark, spaces that continue folded lines). Generated by `pnpm fixtures`.\n[*]\nend_of_line = unset\ninsert_final_newline = unset\ntrim_trailing_whitespace = false\ncharset = unset\n',
  );
  return new Map([...out].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)));
}

/** The zone fixture hook (`events-file.ts`) that writes `fixtures/ics`. */
export function icsFixtureHook(zones: ZoneResolver): GeneratedFile[] {
  return [...buildIcsFiles(zones)].map(([path, content]) =>
    typeof content === 'string' ? { url: new URL(path, ICS_DIR_URL), text: content } : { url: new URL(path, ICS_DIR_URL), bytes: content },
  );
}

// ---------------------------------------------------------------------------
// README
// ---------------------------------------------------------------------------

const ROUND_TRIP_TEXT: Readonly<Record<RoundTrip, string>> = {
  'as-read': 'as read',
  'zones-added': 'as read, plus generated VTIMEZONEs',
};

function readme(): string {
  const span = (w: { from: string; to: string }) => `${w.from} to ${w.to}`;
  const cases = ICS_CASES.map((c) => {
    let windows = '';
    if (c.expansions !== undefined) {
      const isDefault = (e: { deviceZone: string; window: WindowSpec }) => e.window === DEFAULT_WINDOW && (DEVICE_ZONES as readonly string[]).includes(e.deviceZone);
      const custom = c.expansions.filter((e) => !isDefault(e)).map((e) => `${e.deviceZone} ${span(e.window)}`);
      windows = ` ${c.expansions.filter(isDefault).length === DEVICE_ZONES.length ? 'Also expanded in' : 'Expanded only in'}: ${custom.join('; ')}.`;
    } else if (c.extraWindows !== undefined) {
      windows = ` Also expanded ${c.extraWindows.map(span).join(' and ')}.`;
    }
    return `| \`${c.file}\` | ${c.tests}${windows} | ${c.source} | ${ROUND_TRIP_TEXT[c.roundTrip]} |`;
  });
  const procedures = (specs: readonly ProcedureSpec[]) => specs.map((s) => `- \`${s.file}\`: ${s.description}`).join('\n');
  return `# fixtures/ics

The conformance set of the \`.ics\` module (docs/EVENTS.md §5.4, §5.6), shared by TypeScript
(\`packages/core\`) and C# (\`windows/Thirteen.Core\`, task W2). Generated by \`pnpm fixtures\` from
\`packages/core/scripts/ics-*.ts\`; never edit a file here by hand: \`packages/core/test/ics/fixtures.test.ts\`
fails until the committed files equal freshly generated ones, and the generator removes files it no
longer writes. \`index.json\` lists every case and procedure (\`"complete": true\`: ports fail on unknown
entries).

Inputs are anonymized copies of what other apps write, kept in \`packages/core/scripts/ics-cases.ts\` as
content lines so that their bytes (line ends, folds, a byte order mark) are exact; inputs "as Thirteen
exports them" are generated with the engine. \`.gitattributes\` and \`.editorconfig\` here keep every byte
as written.

## Layout

\`\`\`
index.json                  the manifest: version, complete, counts, every case and procedure file
cases/*.ics                 inputs
expected/*.json             per input: calendar fields, warnings, UID groups, expanded occurrences
roundtrip/*.ics             serializeICalendar(parseICalendar(input)) for every case
edits/*.json, edits/*.ics   edits applied to one UID group, and the exact document after each step
imports/*.json, *.ics       a target document, the files imported into it in order, the exact documents
restore/                    two local calendars and a subscription as Thirteen exports them, the same
                            as one zip, an earlier export, and restore.json with the exact results
\`\`\`

## How to run a case

Every value that needs zone data is computed through the \`RecordedZoneResolver\` built from the
\`zoneOffsets\` of \`fixtures/events.json\` (§5.5), never through the platform's own zone data.

- Read \`cases/{name}.ics\` with \`parseICalendar(text, { calendarId, zones })\`, \`calendarId\` being the file
  name without \`.ics\` (it seeds derived UIDs and is the first part of every occurrence key). Compare
  \`calendar\` (\`name\`, \`color\`, \`refreshInterval\`, the calendar properties in \`extra\`, the
  \`VTIMEZONE\`s read with their observance count, the components kept as read in \`others\`),
  \`warnings\` and \`groups\`.
- For each entry of \`expansions\`, compare \`expandCalendar(calendar, deviceZone, zones, window, 'ifc',
  { calendarId })\` (\`eventsFromCalendar\` plus its warnings) with \`occurrences\` and \`warnings\`.
  Every case is expanded in Europe/Tallinn and America/New_York from 2026-01-01T00:00 to
  2027-12-31T24:00; cases about other years add their own windows and device zones.
- \`roundtrip/{name}.ics\` is \`serializeICalendar(calendar, zones, { now: "${ICS_NOW}" })\`, byte for byte.
  For "as read" cases it equals the input with CRLF line ends and without a byte order mark; for the
  others it is that plus a generated \`VTIMEZONE\` for each zone the input uses without defining it.

JSON forms (as in \`fixtures/events.json\`, §5.5): dates \`"YYYY-MM-DD"\`, wall clocks \`"YYYY-MM-DDTHH:MM"\`;
\`IcsDateValue\` as \`{"kind":"date","date"}\`, \`{"kind":"floating"|"utc","value"}\` or
\`{"kind":"zoned","value","tzid"}\`; \`IcsEvent\` with every field of §5.4 except \`raw\` and \`original\`, in
declaration order, \`rrules\` and \`exrules\` as their canonical \`formatRRule\` text, \`line\` the 1-based line
the component begins on; properties as \`{"name","params":[[name, value]],"value"}\` exactly as written;
warnings as \`{"line","code","detail"}\` (\`detail\` is informative: compare \`line\` and \`code\`);
occurrences as \`EventOccurrence\` JSON \`{"key","calendarId","title","allDay","start","end"}\`, keys per
§3.2.

## Cases

| File | What it tests | Source | Round trip |
|---|---|---|---|
${cases.join('\n')}

## Procedures

A procedure file holds scenarios. A scenario starts from a file of this set (\`{"file"}\`) or from a new
empty Thirteen calendar (\`{"new": {"calendarId","name","color"}}\`, \`newICalendar\` written at \`now\`), and
each step starts from the previous step's expected document, read with \`parseICalendar(text,
{ calendarId, zones })\`. After the step, \`serializeICalendar(calendar, zones, { now })\` must equal the
step's \`expected\` file byte for byte; steps with \`expansions\` also give the occurrences of that document.

- \`edit\`: \`changes\` applied in order. \`set\` replaces the given fields (JSON as above) of one member of
  a UID group (the master when \`recurrenceId\` is null); \`untils\` rewrites the \`UNTIL\` of the listed
  rules of the master with \`withRetimedUntils\` (\`{"rule","index","endDate"}\`, after the \`set\` before it);
  \`add\` adds a new group whose master is the given event; \`remove\` removes a group. Every touched group
  goes through \`replaceGroup\`, so it is re-serialized, the properties of untouched fields as read
  (§4.9). The field values are the ones the platform computes (\`retimeExceptions\`, \`allDayEnd\`,
  \`untilFor\`, \`SEQUENCE\` plus one and \`LAST-MODIFIED\` at \`now\` for a user change).
- \`import\`: the file imported into the calendar (below); \`result\` gives the UID groups counted
  (§2.17 step 4).
- \`restore\`: the file restored into the calendar (below); \`result\` gives the backup's UID groups
  counted.

### Edits

${procedures(EDIT_SPECS)}

### Imports

${procedures(IMPORT_SPECS)}

How an import merges (§2.17 step 3, §3.6; \`importCalendar\` in \`packages/core/scripts/ics-procedures.ts\`):

1. Read the file with the target calendar's id; rename its file-defined zones that the target defines
   differently (\`renameCollidingTimeZones\`).
2. Several masters with one UID: the newest (\`groupVersion\`, the first of equals) is used, the others
   count as skipped.
3. A group whose UID is new to the target is added with its raw text and the baseline line
   \`X-THIRTEEN-IMPORTED-LAST-MODIFIED\` (\`withImportBaseline\` with its \`groupVersion\`).
4. A group whose UID the target holds replaces it when its version is later than the stored group's
   baseline, or, when the stored group has none, than the stored group's own version; otherwise it
   counts as unchanged.
5. A group without a master merges override by override: a new \`RECURRENCE-ID\` is added, a stored
   override is replaced by the rule of step 4 applied to that override; each added or replaced override
   carries its own baseline; the stored master is never touched. The group counts as updated when
   anything changed.
6. The target keeps its \`VTIMEZONE\` of a \`TZID\` and takes the incoming one of a \`TZID\` it lacks
   (\`mergeTimeZones\`); the writer drops unused ones and rebuilds generated ones whose years grew.

Added and replaced groups keep their raw text (\`replaceGroup\` with \`keepRaw\`).

### Restore

- \`${RESTORE_SPEC.file}\`: ${RESTORE_SPEC.description}

\`restore/\` holds \`Personal.ics\` and \`Work.ics\` (local calendars) and \`Holidays in Estonia.ics\` (a
subscription: its last fetched copy with \`X-THIRTEEN-SUBSCRIPTION-URL\` and
\`X-THIRTEEN-SUBSCRIPTION-INTERVAL\`), each with its \`X-THIRTEEN-CALENDAR-ID\`, name and color, and
\`${RESTORE_ZIP.slice('restore/'.length)}\`, the same three files as the web export writes them: an
uncompressed zip (stored entries, UTF-8 names, dated 2026-10-19 09:41). \`restore.json\` lists them as the
restore dialog does (\`calendars\`). A restore merges version against version (\`restoreCalendar\`):
a group only in the backup is added, a group in both is replaced when the backup's \`groupVersion\` is
later and counted as kept newer when the calendar's is later, a group only in the calendar stays;
baselines are ignored and none are added.

## ical.js

\`packages/core/test/ics/oracle.test.ts\` expands every case with \`ical.js\` 2.2.1 (its zone registry
holding only the round-trip text's own \`VTIMEZONE\`s) and requires the same occurrences in every window of
\`expected/\`, on a UTC device. Where \`ical.js\` does not implement RFC 5545 or §5.4 the test lists the
UID and the reason.
`;
}
